# Preserve every already-read context paragraph and exact register row as a separate lead.
notes=(ROOT/'sources/notes/pro/MPL_36_002-052_notes.md').read_text()
entry_map={int(r['entry_id'].split('#')[-1]):r['item_id'] for r in csv.DictReader((S/'entries.tsv').open(),delimiter='\t')}
contexts=[]
for m in re.finditer(r'^### N(\d+) .*?\n(.*?)(?=^### |\Z)',notes,re.M|re.S):
 n=int(m.group(1));b=m.group(2)
 q=re.search(r'\*\*Context comparison:\*\*\s*(.*?)(?=\n\n|\Z)',b,re.S)
 if not q: continue
 txt=' '.join(q.group(1).splitlines());contexts.append((n,txt))
 ev='Verbatim earlier-run context lead preserved after reading the whole entry. External run reports are unavailable; verified supplied-source relations have separate folder rows. No theorem or referee verdict is inherited.'
 if n==91: ev+=' Current A36-01/A36-02 are now read; the earlier absence of those scans is superseded, while the Hua report remains unavailable.'
 add('our projects',f'MPL_36_002-052#'+str(n),'Earlier-run context targets named verbatim in what',txt,ev,entry_map.get(n,'')+f';source N{n:02}')
block=notes.split('| Exact register ID |',1)[1].split('**Planning disposition:**',1)[0]
register=[]
for line in block.splitlines():
 if not line.startswith('|'): continue
 cells=[x.strip() for x in line.strip().strip('|').split('|')]
 if len(cells)!=5 or cells[0].startswith('---'):continue
 register.append(cells)
 rid,status,source,relation,nids=cells
 ev='Earlier-run supplied register description only; the named external source was not supplied. Current-source endpoints, where available, are checked in separate folder rows; RETURNED or certified neighbouring IDs do not establish this mathematical claim.'
 if 'Hua' in rid: ev+=' Current A36 is now available and fully reviewed; this corrects the historical absence-of-pages disposition, not the unseen Hua report.'
